// GoldenDump <oracle.xls> <outPrefix> : freeze the REAL legacy plugin's output as TEXT (so the binary .xls and the legacy server are no longer needed to run the parity gates).
//   <prefix>.cells.tsv  : sheet \t addr \t kind(s|n|f|b) \t value|formula     (Output + Process, non-blank cells only)
//   <prefix>.styles.tsv : Output only: addr \t font \t fontColor \t fill \t border \t numfmt \t align   (cells that are non-blank OR carry a non-default style)
//                         plus "#merged\tN", "#col\tc\twidth\thidden", "#row\tr\theight"
import java.io.*; import java.util.*; import org.apache.poi.ss.usermodel.*; import org.apache.poi.hssf.usermodel.*; import org.apache.poi.hssf.util.HSSFColor;
public class GoldenDump {
 static String esc(String s){ return s.replace("\\","\\\\").replace("\t","\\t").replace("\n","\\n").replace("\r","\\r"); }
 static String rgb(Workbook w, Color c){ if(c instanceof HSSFColor){ short[] t=((HSSFColor)c).getTriplet(); return String.format("%02X%02X%02X",t[0],t[1],t[2]); } return "-"; }
 static boolean plain(CellStyle q){ return q.getFillPattern()==FillPatternType.NO_FILL && q.getBorderTop()==BorderStyle.NONE && q.getBorderBottom()==BorderStyle.NONE && q.getBorderLeft()==BorderStyle.NONE && q.getBorderRight()==BorderStyle.NONE && q.getDataFormatString().equals("General"); }
 public static void main(String[] a) throws Exception { HSSFWorkbook w=new HSSFWorkbook(new FileInputStream(a[0]));
  try(PrintWriter p=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[1]+".cells.tsv"),"UTF-8"))){ for(String sn:new String[]{"Output","Process"}){ Sheet s=w.getSheet(sn); for(Row r:s) for(Cell c:r){ String k,v; switch(c.getCellType()){ case STRING: k="s"; v=c.getStringCellValue(); if(v.isEmpty()) continue; break; case NUMERIC: k="n"; v=Double.toString(c.getNumericCellValue()); break; case BOOLEAN: k="b"; v=String.valueOf(c.getBooleanCellValue()); break; case FORMULA: k="f"; v=c.getCellFormula(); break; default: continue; } p.println(sn+"\t"+c.getAddress().formatAsString()+"\t"+k+"\t"+esc(v)); } } }
  try(PrintWriter p=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[1]+".styles.tsv"),"UTF-8"))){ HSSFSheet s=w.getSheet("Output"); p.println("#merged\t"+s.getNumMergedRegions()); int maxc=0; for(Row r:s) if(r.getLastCellNum()>maxc) maxc=r.getLastCellNum();
   for(int c=0;c<=maxc;c++) p.println("#col\t"+c+"\t"+s.getColumnWidth(c)+"\t"+s.isColumnHidden(c));
   for(Row r:s){ p.println("#row\t"+r.getRowNum()+"\t"+r.getHeight()); for(Cell c:r){ CellStyle q=c.getCellStyle(); if(c.getCellType()==CellType.BLANK && plain(q)) continue; Font f=w.getFontAt(q.getFontIndex()); Color fc=w.getCustomPalette().getColor(((HSSFFont)f).getColor());
     p.println(c.getAddress().formatAsString()+"\t"+f.getFontName()+"/"+f.getFontHeightInPoints()+"/b"+f.getBold()+"/i"+f.getItalic()+"/u"+f.getUnderline()+"\t"+rgb(w,fc)+"\t"+(q.getFillPattern()!=FillPatternType.NO_FILL? q.getFillPattern()+"/"+rgb(w,q.getFillForegroundColorColor()):"none")+"\t"+q.getBorderTop()+","+q.getBorderBottom()+","+q.getBorderLeft()+","+q.getBorderRight()+"\t"+esc(q.getDataFormatString().replace("\\(","(").replace("\\)",")").replace("\\-","-"))+"\t"+q.getAlignment()+"/"+q.getVerticalAlignment()+"/"+q.getWrapText()); } } } }}
